// Moth lantern: pale moths loop round a hanging lantern and leave soft trails. Every beat pushes each moth a
// notch along its loop and flings the loops a little wider, the lantern breathes with the bass, the mids
// stretch the loops, and the treble lights the dust in the air.
HL.mk('Hearth - Moth lantern', {
  frame: `a.q7 = (s.tt = (s.tt || 0) + dt);`,
  fn: `
float swing(float t) { return 0.22 * sin(t * 0.85) + 0.03 * sin(t * 2.1 + 1.0); }
const vec2 PV = vec2(0.0, 0.66);
vec2 ringPos(float t) { float a = swing(t); return PV + 0.50 * vec2(sin(a), -cos(a)); }
vec2 lampPos(float t) { float a = swing(t); return PV + 0.69 * vec2(sin(a), -cos(a)); }

vec2 mothPos(float fi, float th, float stretch) {
  float a = 0.15 + 0.62 * h1(fi + 1.0);
  float b = a * (0.36 + 0.30 * h1(fi + 2.0));
  float tilt = (h1(fi + 3.0) - 0.5) * 1.7;
  vec2 o = vec2(a * cos(th), b * sin(th)) * (1.0 + 0.10 * sin(th * 3.0 + fi)) * stretch;
  // the moths chase the lamp as it swings, each a little behind it
  return rot2(o, tilt) + lampPos(q7 - 0.25 - 0.5 * h1(fi + 4.0));
}
`,
  warp: `
  vec2 p = P(uv);
  vec3 prev = texture(sampler_main, uv).rgb;
  vec2 LC = lampPos(q7);
  float r = length(p - LC);
  float breath = 0.50 + 0.40 * q2 + 0.50 * q3;
  vec3 sc = vec3(0.010, 0.018, 0.012) + vec3(1.0, 0.60, 0.20) * breath * (0.15 / (1.0 + pow(r / 0.15, 2.0)) + 0.045 / (1.0 + pow(r / 0.5, 2.0)));
  // dust in the lamplight
  vec2 g = p * 24.0 + vec2(q7 * 0.13, q7 * 0.2);
  vec2 id = floor(g), jf = h22(id);
  float mote = smoothstep(0.08, 0.0, length(fract(g) - 0.2 - 0.6 * jf)) * step(0.7, h2(id + 3.0));
  sc += vec3(1.0, 0.8, 0.45) * mote * (0.08 + 0.7 * q4 * h2(id + 9.0)) / (1.0 + r * 3.0);
  vec3 c = max(prev * 0.62, sc);
  for (int i = 0; i < 20; i++) {
    float fi = float(i);
    float dir = h1(fi + 5.0) < 0.5 ? -1.0 : 1.0;
    float sp = 0.22 + 0.30 * h1(fi + 6.0);
    float th = dir * (q1 * sp + q27 * 0.30 * (0.5 + h1(fi + 7.0))) + fi * 2.4;
    float stretch = 1.0 + 0.20 * q3 * (h1(fi + 8.0) - 0.25) + 0.10 * q8 * sin(fi * 1.3);
    vec2 pos = mothPos(fi, th, stretch);
    pos.y += 0.010 * sin(q7 * 3.0 + fi);
    vec2 q = p - pos;
    float s = 0.011 + 0.013 * h1(fi + 9.0);
    if (dot(q, q) > s * s * 9.0) continue;
    vec2 d = normalize(mothPos(fi, th + dir * 0.02, stretch) - mothPos(fi, th, stretch));
    q = vec2(dot(q, d), dot(q, vec2(-d.y, d.x))) / s;
    float fl = 0.30 + 0.70 * abs(sin(q7 * 34.0 + fi * 5.0));
    float ay = abs(q.y), wy = ay / fl;
    float e = 1.5 / (s * texsize.y);
    float fw = smoothstep(e, -e, length(vec2((q.x - 0.25) * 1.1 + 0.45 * wy, wy - 0.80) / vec2(0.85, 0.82)) - 1.0);
    float hw = smoothstep(e, -e, length(vec2(q.x + 0.50, wy - 0.52) / vec2(0.55, 0.56)) - 1.0);
    float wing = max(fw, hw * 0.92) * step(0.03, ay);
    float rr = length(vec2(q.x - 0.1, wy));
    float band = 0.5 + 0.5 * sin(rr * 10.0 + fi);
    vec3 wc = mix(vec3(0.90, 0.84, 0.66), vec3(0.56, 0.42, 0.25), 0.40 * band + 0.3 * h1(fi + 11.0));
    wc = mix(wc, vec3(0.20, 0.13, 0.07), smoothstep(0.17, 0.08, length(vec2(q.x - 0.28, wy - 0.85))));
    wc = mix(wc, vec3(0.98, 0.92, 0.75), smoothstep(0.07, 0.03, length(vec2(q.x - 0.28, wy - 0.85))));
    wc *= 0.80 + 0.20 * smoothstep(1.6, 0.6, rr);                  // darker fringe
    wc *= 0.85 + 0.15 * sin(atan(wy, q.x - 0.1) * 26.0);            // wing veins
    float body = smoothstep(e, -e, length(q / vec2(0.85, 0.17)) - 1.0);
    float lit = 0.60 + 0.85 / (1.0 + pow(length(pos - LC) / 0.3, 2.0)) + 0.30 * q3;
    c += vec3(1.0, 0.8, 0.5) * 0.06 * lit * exp(-dot(q, q) * 0.45);
    c = mix(c, wc * lit, wing);
    c = mix(c, vec3(0.30, 0.22, 0.12) * lit, body);
  }
  ret = c;
`,
  cfn: `uniform sampler2D sampler_hearthlantern;

float swing(float t) { return 0.22 * sin(t * 0.85) + 0.03 * sin(t * 2.1 + 1.0); }
const vec2 PV = vec2(0.0, 0.66);
vec2 ringPos(float t) { float a = swing(t); return PV + 0.50 * vec2(sin(a), -cos(a)); }
vec2 lampPos(float t) { float a = swing(t); return PV + 0.69 * vec2(sin(a), -cos(a)); }
`,
  comp: `
  vec2 p = P(uv);
  vec3 c = texture(sampler_main, uv).rgb;
  c += texture(sampler_blur1, uv).rgb * vec3(0.34, 0.25, 0.13);
  float px = 1.0 / texsize.y;
  float a = swing(q7);
  // lamp space: origin at the hanging ring, y pointing down the lamp
  vec2 l = rot2(p - PV, -a); l = vec2(l.x, -l.y - 0.50);
  // the rope, with a few leaves of the vine that climbs it
  float rope = smoothstep(0.0034 + px, 0.0034 - px, abs(l.x + 0.0015 * sin(l.y * 60.0))) * step(l.y, 0.004);
  c = mix(c, vec3(0.80, 0.77, 0.64) * (0.55 + 0.25 * sin(l.y * 400.0 + l.x * 300.0)), rope);
  for (int i = 0; i < 7; i++) {
    float fi = float(i), sg = mod(fi, 2.0) < 0.5 ? 1.0 : -1.0;
    vec2 q = rot2(l - vec2(sg * 0.004, -0.04 - 0.055 * fi), sg * (0.9 + 0.4 * h1(fi)) + 0.15 * sin(q7 * 1.4 + fi)) / 0.030;
    vec4 lf = leaf(vec2(q.x * sg, q.y), 0.34, fi + 3.0, px / 0.030, vec3(0.16, 0.30, 0.09), vec3(0.34, 0.40, 0.12), 0.0);
    c = mix(c, lf.rgb * 0.8, lf.a);
  }
  // the Hearth lantern itself
  float LH = 0.300, LW = LH * 240.0 / 436.0;
  vec2 tuv = vec2(l.x / LW + 0.5, (l.y + 0.012) / LH);
  if (tuv.x > 0.0 && tuv.x < 1.0 && tuv.y > 0.0 && tuv.y < 1.0) {
    vec4 t = texture(sampler_hearthlantern, tuv);
    float fk = 0.82 + 0.10 * sin(q7 * 9.0) + 0.06 * sin(q7 * 23.0) + 0.45 * q3 + 0.2 * q2;
    // the glass and the flame flicker; the cream frame only catches a little of it
    float warmth = smoothstep(0.15, 0.5, t.r - t.b);
    vec3 col = t.rgb * mix(0.80 + 0.08 * q3, fk, warmth);
    c = mix(c, col, t.a);
  }
  ret = finish(c, p, 0.7);
`,
});
window.hearthImages = Object.assign(window.hearthImages || {}, { hearthlantern: { data: 'data:image/png;base64,', width: 240, height: 436 } });
